package com.manishrawat.realestate.util; import org.mindrot.jbcrypt.BCrypt; public final class PasswordUtil{private PasswordUtil(){} public static String hash(String p){if(p==null)throw new IllegalArgumentException("Password is required.");return BCrypt.hashpw(p,BCrypt.gensalt(12));} public static boolean matches(String p,String h){if(p==null||h==null||!h.startsWith("$2"))return false;try{return BCrypt.checkpw(p,h);}catch(IllegalArgumentException e){return false;}}}
